USE dbMaster;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID('dbo.tblCustomers','U') IS NULL
CREATE TABLE dbo.tblCustomers(CustomerId INT IDENTITY PRIMARY KEY,CustomerCode NVARCHAR(30) NOT NULL UNIQUE,CustomerName NVARCHAR(200) NOT NULL,TaxId VARCHAR(13) NOT NULL DEFAULT '0',BranchCode VARCHAR(5) NOT NULL DEFAULT '00000',BillingAddress NVARCHAR(1000) NULL,ShippingAddress NVARCHAR(1000) NULL,ContactName NVARCHAR(100) NULL,Phone NVARCHAR(150) NULL,Email NVARCHAR(150) NULL,CustomerTypes VARCHAR(100) NOT NULL,Note NVARCHAR(1000) NULL,SourceTaxId NVARCHAR(50) NULL,SourceFile NVARCHAR(200) NULL,IsActive BIT NOT NULL DEFAULT 1,Revision INT NOT NULL DEFAULT 1,CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('dbo.tblCustomerAudit','U') IS NULL
CREATE TABLE dbo.tblCustomerAudit(AuditId BIGINT IDENTITY PRIMARY KEY,CustomerId INT NOT NULL REFERENCES dbo.tblCustomers(CustomerId),Actor NVARCHAR(100) NOT NULL,Action VARCHAR(20) NOT NULL,BeforeJson NVARCHAR(MAX) NULL,AfterJson NVARCHAR(MAX) NOT NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME());
COMMIT;
